COMMENT ON COLUMN zarit_burden_interview_grade_flag.deleted_at IS
    'Timestamp when the row was soft-deleted.';
COMMENT ON COLUMN zarit_burden_interview_grade_flag.zarit_burden_interview_grade_id IS
